using Spirit604.CityEditor.Road;
using Spirit604.Collections.Dictionary;
using Spirit604.Extensions;
using System;
using System.Collections.Generic;
using UnityEngine;

namespace Spirit604.DotsCity.ThirdParty.MVR
{
    [CreateAssetMenu(fileName = "MVR_Config", menuName = "Spirit604/MVR_Config")]
    public class MVR_Config : ScriptableObject
    {
        [Serializable]
        public class PrefabDictionary : AbstractSerializableDictionary<string, RoadSegmentCreator> { }

        public PrefabDictionary Prefabs = new PrefabDictionary();

        [Tooltip("List of intersections to be generated automatically")]
        public List<string> AutoGeneratedIntersections = new List<string>();

        public void AddPrefab(string key, RoadSegmentCreator sceneObject)
        {
            RoadSegmentCreator prefab = null;

#if UNITY_EDITOR
            prefab = UnityEditor.PrefabUtility.GetCorrespondingObjectFromSource(sceneObject.gameObject).GetComponent<RoadSegmentCreator>();
#endif

            if (!Prefabs.ContainsKey(key))
            {
                Prefabs.Add(key, prefab);
                EditorSaver.SetObjectDirty(this);
                Debug.Log($"MVR_Config. Prefab {prefab.name} with '{key}' key added.");
            }
            else
            {
                Debug.LogError($"MVR_Config. Prefab with '{key}' key already exist.");
            }
        }
    }
}